package com.bank.export.service;

import com.bank.export.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class CsvExportService {
    private static final Logger log = Logger.getLogger(CsvExportService.class.getName());

    public List<String> toCsvRows(List<Employee> employees) {
        log.info(() -> "Serialising " + employees.size() + " employees to CSV rows");
        return employees.stream()
                // Join fields with commas; toPlainString avoids scientific notation.
                .map(e -> e.getName() + ","
                        + e.getDepartment() + ","
                        + e.getSalary().toPlainString())
                .collect(Collectors.toList());
    }
}
