package com.bank.export;

import com.bank.export.model.Employee;
import com.bank.export.service.CsvExportService;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT",    new BigDecimal("95000")),
            new Employee("Priya",  "Sales", new BigDecimal("72000")),
            new Employee("Amit",   "HR",    new BigDecimal("48000"))
        );

        List<String> rows = new CsvExportService().toCsvRows(staff);
        rows.forEach(r -> log.info(() -> "CSV row: " + r));
    }
}
